// 덧셈·뺄셈 동적 문제 생성 보조 함수 (100 이하)
window.generateDynamicMathQuestion = function() {
  const isAdd = Math.random() < 0.55;
  let a, b, ans, op;
  if (isAdd) {
    a = Math.floor(Math.random() * 60) + 1;
    b = Math.floor(Math.random() * (100 - a)) + 1;
    ans = a + b;
    op = '+';
  } else {
    a = Math.floor(Math.random() * 85) + 10;
    b = Math.floor(Math.random() * (a - 1)) + 1;
    ans = a - b;
    op = '-';
  }
  const wrongs = new Set();
  const deltas = [-10, -5, -3, -2, -1, 1, 2, 3, 5, 10];
  while (wrongs.size < 3) {
    const d = deltas[Math.floor(Math.random() * deltas.length)];
    const cand = ans + d;
    if (cand >= 0 && cand <= 100 && cand !== ans) {
      wrongs.add(String(cand));
    }
  }
  const options = [String(ans), ...Array.from(wrongs)];
  for (let i = options.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [options[i], options[j]] = [options[j], options[i]];
  }
  return {
    category: 'math',
    question: `다음 계산의 알맞은 답은 무엇일까요?\n【 ${a} ${op} ${b} = ? 】`,
    options,
    answer: String(ans)
  };
};
